"""headtex_toonuv.py STEM SEED... : cartoon redraw of a UV texture IN ITS OWN LAYOUT (original as the klein reference, layout locked), aligned + colour-locked -> headtex/<stem>_s<seed>_fin.png (cartoon prompts)"""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
import headtex_gen as G, headtex_fin as F
T = G.T
LOCK = ("This is a flattened UV texture sheet for a 3D model, not a portrait: keep every shape, position and proportion exactly the same as the input, do not re-frame, re-scale, move or re-pose anything, and add no new objects. "
        "Redraw it as a clean, stylised cartoon in the manner of a hand-painted 1930s pulp-adventure video game: smooth simplified painted shapes, soft cel shading with gentle highlights, bold clean readable features, no pores, no freckles, no wrinkles, no photographic texture. ")
PROMPTS = {
 "cpsuit128": LOCK + "It is the front panel of a dark brown leather aviator flight jacket, a piece of clothing only (there is no person, no face and no head in it): at the top left a big warm tan-brown fur collar drawn as clean cartoon fur tufts, below it a diagonal zippered placket, smooth dark brown leather with a few soft cel-shaded folds and light highlights where the input is light, a stitched flap pocket in the lower part, and a darker brown ribbed waistband across the very bottom. Clean cartoon colours, smooth painted leather, no photographic texture.",
 "cpsuit128_01": LOCK + "It is the front panel of a dark brown leather aviator flight jacket, a piece of clothing (there is no face or head in it): in the top-left corner a small plain patch of bare neck skin in warm tan with a white scarf below it, next to a big warm tan-brown fur collar drawn as clean cartoon fur tufts, a diagonal zippered placket, smooth dark brown leather with a few soft cel-shaded folds and light highlights, a small round green badge with a black centre on the chest, a stitched flap pocket with a dark opening above it, and a darker brown ribbed waistband across the very bottom. Clean cartoon colours, smooth painted leather.",
 "cpsuit128_02": LOCK + "It is a patch of smooth dark brown leather flight jacket material with a few soft cel-shaded creases and gentle highlights where the input is light, and a narrow warm tan-brown fur or knit trim band along the very bottom edge. A piece of clothing only (no person, no face). Clean cartoon colours, smooth painted leather, no photographic texture.",
 "cphead": LOCK + "It is the right half of the head of a 1930s aviator, unwrapped flat, with the middle of the face at the right edge: a smooth dark brown leather flying helmet covering the top, back and sides of the head, simple soft highlight on the crown, a thin dark leather strap running down in front of the ear to a chinstrap under the jaw; on the right edge the face with warm tan cartoon skin, half of a nose, half of a closed calm mouth and one round steel-rimmed aviator goggle with dark teal lens and a thick black leather padding, a goggle strap across the helmet; at the bottom the bare neck in the same warm tan skin, smooth with no stubble. Every area is drawn in clear, sharp, finished detail, nothing smudged or blurred.",
 "womanface": LOCK + "It is the front of a smiling young woman's face squeezed into a narrow strip: dark brown skin, smooth hairless skin with no stubble, dark brown eyes with a white highlight and simple dark eyelashes, simple dark eyebrows, a small nose, a wide happy smile with clean white teeth and glossy red lips; at the top the edge of a dark brown leather flying helmet (no visible hair).",
 "womanarm": LOCK + "It is the upper arm and hand of a young woman: a red sleeve at the top, then a smooth arm and hand with the same dark brown skin as her face (a rich medium-dark brown, not orange), simple clean fingers, no freckles or hair on the skin.",
 "fbhead1": LOCK + "It is one half of the head of a cheerful, kindly elderly man, unwrapped flat: his face on the right with the middle of the face at the right edge (half of the nose, half of a friendly closed-mouth smile with a hint of clean white teeth, one dark brown eye with a white highlight behind a thin round dark wire glasses rim, a soft white eyebrow), "
            "smooth warm pink-beige cartoon skin with simple soft shading, no wrinkles, no stubble; a simple pink ear in the middle; a thick white woolly knitted cap covering the top, back and sides of the head drawn as soft clean off-white wool with simple cel-shaded folds; "
            "along the bottom a warm brown tweed coat collar. Every area is drawn in clear, sharp, finished detail, nothing smudged or blurred.",
 "fbsuit128_01": LOCK + "It is the front panel of a long khaki-tan canvas overcoat, a piece of clothing only (there is no person, no face and no head in it): along the left edge the open neck of the coat, at the very top-left corner a small plain pink patch of bare neck skin, below it a white shirt collar and a dark tie, framed by a wide warm brown fur lapel; the rest is smooth khaki-tan coat fabric with a few soft cel-shaded folds, soft light highlights where the input is light, and a rounded pocket flap at the lower left. Clean flat cartoon colours, simple painted fabric.",
 "fbsuit128_02": LOCK + "It is a patch of smooth khaki-tan canvas coat fabric with a few soft cel-shaded folds and soft light highlights where the input is light, and a darker stitched seam band across the bottom. Clean flat cartoon colours, simple painted fabric, no fur, no hair.",
 "womanchest": LOCK + "It is the front of a young woman's deep red short-sleeved cotton top, a piece of clothing (no face, no head): at the top centre the bare skin of her neck and collarbones inside a round neckline, in the same rich medium-dark brown skin as her arms (not orange); the rest is smooth deep red fabric with a few soft cel-shaded folds and gentle highlights, clean dark outlines only at the neckline. The plain grey areas at the edges are background. Clean flat cartoon colours, no leather, no straps, no texture noise.",
 "woman1": LOCK + "It is a patch of a young woman's dark olive-green cotton trousers: smooth olive fabric with a few soft cel-shaded vertical folds and gentle highlights, and along the very top edge a narrow dark brown belt with small tan details where the input has them. Clean flat cartoon colours, simple painted fabric, no stains, no cracks, no texture noise.",
 "womanhead": LOCK + "It is the side and top of a young woman's head wearing a dark brown leather flying helmet: a smooth leather helmet with a large round ear flap over the ear (no visible ear, no hair), a thin chinstrap, the side of her face clearly drawn with a clean cheek and jaw line in smooth dark brown cartoon skin, a dark brown eye with a white highlight and a happy smile with red lips. Every area is drawn in clear, sharp, finished detail, nothing smudged or blurred.",
}
def run(stem, seeds, sab=24.0, sl=8.0):
    for s in seeds:
        ref = G.ref_of(stem); D = G.ROOT / "face_audit/headtex"; rp = D / f"{stem}_ref.png"; ref.save(rp)
        out = D / f"{stem}_s{s}.png"; T.locked_gen_wh(str(rp), str(out), PROMPTS[stem], ref.width // 16 * 16, ref.height // 16 * 16, s); F.fin(stem, s, sl, sab)
if __name__ == "__main__":
    import os; run(sys.argv[1], [int(x) for x in sys.argv[2:]], float(os.environ.get("SAB", 24)), float(os.environ.get("SL", 8)))
